#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> G(N, vector<int>(M));
    int cost[2] = {0, 0};

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            cin >> G[i][j];
            for (int base = 0; base < 2; ++base) {
                int targetParity = base ^ ((i + j) & 1);
                if ((G[i][j] & 1) != targetParity) {
                    ++cost[base];
                }
            }
        }
    }

    int base = (cost[0] <= cost[1] ? 0 : 1);
    cout << cost[base] << '\n';

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            int targetParity = base ^ ((i + j) & 1);
            int value = G[i][j];
            if ((value & 1) != targetParity) {
                ++value;
            }
            if (j) cout << ' ';
            cout << value;
        }
        cout << '\n';
    }

    return 0;
}
